using Microsoft.AspNetCore.Identity;using Microsoft.EntityFrameworkCore;using OpenIddict.Abstractions;using OpenTelemetry.Resources;using OpenTelemetry.Trace;using System.Security.Cryptography.X509Certificates;
var builder=WebApplication.CreateBuilder(args);builder.Services.AddControllers();builder.Services.AddProblemDetails();var connection=builder.Configuration.GetConnectionString("DefaultConnection");if(string.IsNullOrWhiteSpace(connection))throw new InvalidOperationException("ConnectionStrings:DefaultConnection is required.");builder.Services.AddDbContext<ApplicationDbContext>(o=>{o.UseNpgsql(connection);o.UseOpenIddict();});
builder.Services.AddIdentity<ApplicationUser,IdentityRole>(o=>{o.Password.RequiredLength=10;o.Password.RequireDigit=true;o.Password.RequireLowercase=true;o.Password.RequireUppercase=true;o.Password.RequireNonAlphanumeric=true;o.User.RequireUniqueEmail=true;o.Lockout.MaxFailedAccessAttempts=5;o.Lockout.DefaultLockoutTimeSpan=TimeSpan.FromMinutes(15);o.SignIn.RequireConfirmedEmail=false;}).AddEntityFrameworkStores<ApplicationDbContext>().AddDefaultTokenProviders();
builder.Services.AddOpenIddict().AddCore(o=>o.UseEntityFrameworkCore().UseDbContext<ApplicationDbContext>()).AddServer(o=>{var issuer=builder.Configuration["Authentication:Issuer"];if(!string.IsNullOrWhiteSpace(issuer))o.SetIssuer(new Uri(issuer));o.SetAuthorizationEndpointUris("/connect/authorize");o.SetTokenEndpointUris("/connect/token");o.AllowAuthorizationCodeFlow().RequireProofKeyForCodeExchange();o.AllowPasswordFlow();o.AllowRefreshTokenFlow();o.AllowClientCredentialsFlow();o.DisableAccessTokenEncryption();o.RegisterScopes(OpenIddictConstants.Scopes.OpenId,OpenIddictConstants.Scopes.Profile,OpenIddictConstants.Scopes.Email,OpenIddictConstants.Scopes.OfflineAccess,"api","catalog.write","inventory.write","notifications.read.all");if(builder.Environment.IsDevelopment())o.AddDevelopmentEncryptionCertificate().AddDevelopmentSigningCertificate();else{var path=builder.Configuration["Certificates:Path"];var password=builder.Configuration["Certificates:Password"];if(string.IsNullOrWhiteSpace(path))throw new InvalidOperationException("A production OpenIddict certificate is required.");var certificate=X509CertificateLoader.LoadPkcs12FromFile(path,password);o.AddEncryptionCertificate(certificate).AddSigningCertificate(certificate);}o.UseAspNetCore().EnableAuthorizationEndpointPassthrough().EnableTokenEndpointPassthrough();}).AddValidation(o=>{o.UseLocalServer();o.UseAspNetCore();});
builder.Services.AddHostedService<IdentitySeedHostedService>();builder.Services.AddAuthorization();builder.Services.AddOpenTelemetry().WithTracing(t=>t.SetResourceBuilder(ResourceBuilder.CreateDefault().AddService(builder.Environment.ApplicationName)).AddAspNetCoreInstrumentation().AddHttpClientInstrumentation().AddOtlpExporter());builder.Services.AddHealthChecks();
var app=builder.Build();if(builder.Configuration.GetValue<bool>("Database:MigrateOnStartup")){await using var scope=app.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<ApplicationDbContext>().Database.MigrateAsync();}app.UseExceptionHandler();app.UseHttpsRedirection();app.UseAuthentication();app.UseAuthorization();app.MapHealthChecks("/health");app.MapControllers();app.Run();
